INSERT OR REPLACE INTO posts (id,source,source_id,title,content,author,url,published_at,collected_at) VALUES (4511,'dcinside','dc_cheonan_1221','[ 2018.12 ~ 2019.12 전국 주요도시 인구 증감 ]','2018.12             2019.12           증감서울    9,765,623          9,729,107     ( -36,516)부산    3,441,453          3,413,841     ( -27,912)인천    2,954,642          2,957,026     ( +2,384 )대구    2,461,769          2,438,031     ( -23,738)대전    1,489,936          1,474,870     ( -15,066)광주    1,459,336          1,456,458     ( -2,878  )수원    1,201,166          1,194,465     ( -6,701  )울산    1,155,623          1,148,019     ( -7,064  )고양    1,044,189          1,066,351     ( +21,532)용인    1,035,126          1,056,609     ( +21,483)창원    1,053,601          1,044,740     ( -8,861  )성남    954,347             942,724        ( -11,623)청주    837,749             839,566        ( +1,817)부천    843,768             829,996        ( -13,772)화성    758,722             815,396        ( +56,674)남양주 681,828            701,830        ( +20,002)전주    651,091             654,394        ( +3,303 )천안    646,075             652,258        ( +6,183 )안산    660,343             650,918        ( -9,425  )안양    576,831             567,044        ( -9,787  )정리하느라 힘들었다...ㅋㅋ','ㅇㅇ','https://gall.dcinside.com/mgallery/board/view/?id=cheonan&no=1221&page=1','2020-01-01 17:43:25','2026-03-27 00:34:57.725483');
INSERT OR REPLACE INTO posts (id,source,source_id,title,content,author,url,published_at,collected_at) VALUES (4512,'dcinside','dc_cheonan_34','천안 대표 동 정리','천안 대표 동 정리두정동 ㅡ 저녁에 좆병신들 넘쳐남 평소에는 그렇다쳐도 명절때 가면 븅신 자지세끼들이 애미는 힘들게 반찬하고 있는데 여자번호 한번 따보겠다고 하이에나처럼 어슬렁거린다 한심의 극치 ㅋㅋㅋ그런데 이땐 진짜 보지 아무도없음ㅋㅋㅋㅋ 자지만 자릉내 풍기면서 기웃거림신부동 ㅡ 갓월드백화점이 계신곳 백화점 매출이 전국 최하위권이라 다음엔 없어질 가능성이 크다고 함쌍용동 ㅡ 좆망 로데오거리 / 나머있음 사람이 많이 사는 무난한 동네불당동 ㅡ 교통 씹병신ㅋㅋㅋㅋ뚜벅이 아니면 차 있어야댐 부촌성정동 ㅡ 롯머에게 점령당함 있을건 다 있긴한데 이용하기엔 다 거리가 존나 띄엄띄엄 하고 멈백석동 ㅡ 여기도 교통은 병신 불당동 다음 부자동네로 미는중신방동 ㅡ 이마트 근처 동네는 살만한데 그 밑에는 신방도서관 밖에 볼거없음청수동 ㅡ 양승조가 최근 집중적으로 개발 하고 있는곳 근데 살기엔 아직 쓰레기봉명동 ㅡ 쓰레기 동네. 병신이 많다. 한 끗 차이로 서북구가 아니라 눈물흘리는 사람이 많음 근처에 천안역과 봉명역이 있음에도 불구하고 몰락하고있다. 최근엔 그나마 재개발을 느리게 시작 하고있다.원성동 ㅡ 봉명동과 마찬가지로 망해가는 동네이다 원성동에 오면 건물이 다 허물어져 부숴져가는 가게와 병원이 눈에 띈다.번외+읍 면 리는 살 생각하지 말아라비록 봉명동 원성동을 쓰레기라고 했지만 (물론 쓰레기 맞음)아무리 그렇다고해도 읍 면 리와 비교하면 심히 격분한 그 동 주민에게 뺨맞는 수가 있다목천읍 ㅡ 맛집이 정말 많다. 하지만 살 생각은 하지말아라문명의 혜택이 없어 원시 생활을 해야하는건 뒷전으로 치더라도 일단 동네에 고약한 소똥내가 허벌나게 풍긴다. 어쩔수없는 사정에 의해 만약 이 동네에서 살게 된다면 자살을 하거나 후각세포를 파괴하는 것을 권장. 가끔 맛집 탐방하고 싶을 때 차타고 어쩌다 잠깐 들리는게 좋다.추가 지역 & 내용 댓으로 부탁글삭하고 다시씀','ㅇㅇ','https://gall.dcinside.com/mgallery/board/view/?id=cheonan&no=34&page=1','2017-08-04 04:41:27','2026-03-27 00:34:57.725483');
