INSERT OR REPLACE INTO posts (id,source,source_id,title,content,author,url,published_at,collected_at) VALUES (4597,'dcinside','dc_cheonan_16902','천안공고 불합격한게 가장 행운이다','이유 : 본인 개찐따라 붙었으면 일진먹이감되거나 개양아치되서 담배나 피고다녔음 ㅋㅋ 근데 불합격하니 평준화이라 일반고 갔네 ㅋㅋㅋ 그래서 내가 너무 이게 행운이다 생각함 일반고졸업후 현재 지금도 여미새짓도안하고 담배도 안피고 평범한게 산다 ㅋㅋㅋㅋ근황 : 천안공고불합격하고 일반고졸업후 한기대다니고 내년이가 늦어도 후년에 졸업함 ㅂㅂ만약 천안공고 붙었으면 담배꼴초딸배인생이였음ㅋㅋㅋㅋ 근데 떨어져서 다행이였다 ㅋㅋㅋㅋ (인생최고엿음)(평준화 감사합니다 아니였으면 이보다 더 지옥인 학교가서 인망할뻔 근데 평준화가 그때 나를 살렸다)나도 그사진은 최근에 본거지만 어쩌면 개찐따한테는 잘된듯공고가서 좆뱅이라쳐랔ㅋㅋㅋㅋ 나는 한기대 졸업하고 사무직 갈테니 ㅋㅋ','ㅇㅇ','https://gall.dcinside.com/mgallery/board/view/?id=cheonan&no=16902&page=2','2026-03-13 19:48:23','2026-03-27 00:34:57.725495');
