INSERT OR REPLACE INTO posts (id,source,source_id,title,content,author,url,published_at,collected_at) VALUES (4610,'dcinside','dc_cheonan_16875','외국인들 천안 한달살기 어떠냐?','요즘 한류때문에 한국에 살고싶어하는 외국인들(특히 여성들) 겁나 많던데서울,제주,부산 이런데는 이미 외국인들 썩어 넘쳐서숙소 렌트비가 비싸더라고그래서 천안에 외국인 여행객,유학생,워홀러들 장기 체류자들 대상으로임대업을 해 볼 생각인데위치는 천안역,신세계 버스터미널의 중간 지점 부근으로 하려고실제로 이 부근이 집값이 저렴하고 입지가 좋아서 그런지 외국인들 많이 보이더라','ㅁㄴㅇ','https://gall.dcinside.com/mgallery/board/view/?id=cheonan&no=16875&page=3','2026-03-11 14:51:13','2026-03-27 00:34:57.725497');
