INSERT OR REPLACE INTO posts (id,source,source_id,title,content,author,url,published_at,collected_at) VALUES (4687,'dcinside','dc_cheonan_16743','하도 버스가지고 뭐라고하길레 직접 오늘 타봄..','글쎄.. 별로 그런거 못느꼈는데??일종에 천안버스 밈이 된거같아서그렇게 생각하는거같은데..손 안들어도 일어서 있으니까 세워준던데?난폭운전? 오히려 느려서 답답해죽는줄알았는데..','천갤러','https://gall.dcinside.com/mgallery/board/view/?id=cheonan&no=16743&page=4','2026-02-26 19:16:04','2026-03-27 00:34:57.725508');
