INSERT OR REPLACE INTO posts (id,source,source_id,title,content,author,url,published_at,collected_at) VALUES (6191,'dcinside','dc_cheonan_17590','천안 대장 아파트는 매매 가치 있음?','천안 불당동 대장 아파트는 매매 가치 있음?살 돈도 없지만 나중에 사도 되나 싶은데불당푸르지오 오피스텔 여기는 전세 3억 중후반 하던데 오피스텔 이라서 매매는 비추인데부동산사장은 세대수 많아서 이런 곳은 매매 좋다고 하던데나중에 경기 아파트 포화상태되면 천안도 물쌀 휩쓸려서 오른다고;다들 어케생각함','ㅇㅇ','https://gall.dcinside.com/mgallery/board/view/?id=cheonan&no=17590&page=2','2026-06-01 00:09:20','2026-06-08 06:18:14.543302');
