INSERT OR REPLACE INTO posts (id,source,source_id,title,content,author,url,published_at,collected_at) VALUES (6210,'dcinside','dc_cheonan_17564','기자들이 왜 천안 시내버스에 꽂혔는지 알거같다.','천안 초행길이라서 시내버스 타면서기사한테 "XXX" 가냐고 물어보고 탐안내 방송이랑 전광판에 거기가 뜨길래눈치껏 하차문 앞에 섬근데 문을 안열어줌하차벨을 안눌렀다 이거지(천안은 하차벨 꼭 눌러야 열어줌?)난 분명히 타면서 "기사에게" 물어봤는데초행길인데 창문보고 여기가 어딘지 알겠나?근데 심지어 안내방송이랑 전광판도 틀림 ㅋㅋㅋ내려서 2정거장 걸었다.지나가는 사람들 붙잡고 "XXX"가 어디냐고 물어가며결국 2정거장 거리 걸어서 도착.기자들이 나랑 비슷한 경험했으면안빡칠까?운전은 당연히 난폭운전가족단위로 천안에 왔다면 더더욱 눈 돌아가지.','ㅇㅇ','https://gall.dcinside.com/mgallery/board/view/?id=cheonan&no=17564&page=2','2026-05-29 14:12:37','2026-06-08 06:18:14.543304');
